    size?: ToolbarTextSize;
    className?: string;
}
declare function ToolbarText({ text, size, className }: ToolbarTextProps): kerfjs.SafeHtml;

export { ToolbarText, type ToolbarTextProps, type ToolbarTextSize };
```

