import '@kerfjs/ui/layout.css';

import { delegate, mount, signal } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';

export interface AppCommand {
  id: string;
  label: string;
  keywords?: string[];
}

export interface CommandPaletteCallbacks {
  onClose(): void;
  onRun(command: AppCommand): void;
}

/**
 * Application-local example, not an @kerfjs/ui export. The application owns
 * ranking, history, shortcuts, focus policy, command availability, and copy.
 */
export function mountCommandPaletteAdapter(
  root: HTMLElement,
  commands: AppCommand[],
  { onClose, onRun }: CommandPaletteCallbacks,
): () => void {
  const query = signal('');
  const render = () => {
    const needle = query.value.trim().toLocaleLowerCase();
    const matches = commands.filter((command) => !needle ||
      [command.label, ...(command.keywords ?? [])].some((value) => value.toLocaleLowerCase().includes(needle)));
    return <section class="app-command-palette kui-layout kui-surface-body kui-section-stack" aria-label="Command palette">
      <label for="app-command-query">Search commands</label>
      <input id="app-command-query" type="search" value={query.value} autocomplete="off" data-command-query />
      <p aria-live="polite">{matches.length} matching commands</p>
      <ul aria-label="Matching commands">{matches.map((command) => <li><button type="button" data-action="run-command" data-command-id={command.id}>{command.label}</button></li>)}</ul>
      <footer class="kui-control-cluster" aria-label="Command palette actions">
        <button type="button" data-action="clear-query">Clear search</button>
        <button type="button" data-action="close-palette">Close</button>
      </footer>
    </section>;
  };

  const stopMount = mount(root, render);
  const stopActions = delegateActions(root, 'click', {
    'run-command': (_event, element) => {
      const id = (element as HTMLElement).dataset.commandId;
      const command = commands.find((candidate) => candidate.id === id);
      if (command) onRun(command);
    },
    'clear-query': () => {
      query.value = '';
      root.querySelector<HTMLInputElement>('[data-command-query]')?.focus();
    },
    'close-palette': onClose,
  });
  const stopInput = delegate<HTMLInputElement>(root, 'input', '[data-command-query]', (_event, input) => {
    query.value = input.value;
  });
  const stopEscape = delegate(root, 'keydown', '[data-command-query]', (event) => {
    if ((event as KeyboardEvent).key === 'Escape') onClose();
  });
  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    stopEscape();
    stopInput();
    stopActions();
    stopMount();
  };
}

--- ux-demo/recipes/mount-recipe.ts ---
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import { delegate, mount } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';

import type { RecipeController } from './types.js';

/**
 * Copyable application boundary for a recipe. The caller owns one stable root
 * and retains the returned disposer for that root's lifetime.
 */
export function mountRecipe(root: HTMLElement, controller: RecipeController): () => void {
  const stopMount = mount(root, controller.render);
  const stopActions = delegateActions(root, 'click', {
    'recipe-action': (_event, element) => {
      const target = element as HTMLElement;
      controller.action(target.dataset.recipeCommand ?? '', target);
    },
  });
  const dispatchChange = (_event: Event, element: Element) => controller.change?.(element as HTMLElement);
  const stopChanges = delegate(root, 'change', 'wa-select, wa-input, wa-textarea', dispatchChange);
  const stopInputs = delegate(root, 'input', 'wa-input, wa-textarea', dispatchChange);
  const stopDialogs = delegate(root, 'wa-after-hide', 'wa-dialog', (_event, element) => controller.afterHide?.(element as HTMLElement));
  const stopResize = wireResizableRegions(root, {
    onCommit: ({ id, size }) => controller.resize?.(id, size),
  });

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    stopResize();
    stopDialogs();
    stopInputs();
    stopChanges();
    stopActions();
    stopMount();
  };
}

