import '@kerfjs/ui/layout.css';
import './recipes.css';

import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import { PageHeader } from '@kerfjs/ui/page-header';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { signal } from 'kerfjs';

import type { RecipeFactory } from './types.js';

type ListState = 'loading' | 'empty' | 'populated' | 'stale' | 'error';
const items = ['Audit keyboard focus order', 'Verify 200% zoom layout', 'Publish package migration notes'];

export const createRecipe: RecipeFactory = (announce) => {
  const state = signal<ListState>('loading');
  const populated = () => <ul class="recipe-list__items" aria-label="Release tasks">{items.map((item, index) => <li><strong>{item}</strong><span class="kui-recipe__muted">{index === 0 ? 'In review · Mara' : index === 1 ? 'Ready · Sam' : 'Draft · Inez'}</span></li>)}</ul>;
  const renderBody = () => {
    if (state.value === 'loading') return <EmptyState title="Loading release tasks" detail="The current workspace will appear when data is ready." busy action={<button class="kui-recipe__button" type="button" data-action="recipe-action" data-recipe-command="load">Complete load</button>} />;
    if (state.value === 'empty') return <EmptyState title="No release tasks" detail="Create the first task for this milestone." action={<button class="kui-recipe__button" data-primary="true" type="button" data-action="recipe-action" data-recipe-command="create">Create task</button>} />;
    if (state.value === 'error') return <div class="kui-section-stack"><StateBanner title="Release tasks could not be refreshed" detail="Existing filters are preserved. Try again when the connection recovers." tone="danger" urgency="alert" action={<button class="kui-recipe__button" type="button" data-action="recipe-action" data-recipe-command="retry">Retry</button>} /></div>;
    return <div class="kui-section-stack">{state.value === 'stale' && <StateBanner title="Showing saved results" detail="Refreshing in the background." tone="warning" action={<span class="kui-inline-metadata"><LoadingSpinner label="Refreshing release tasks" /><button class="kui-recipe__button" type="button" data-action="recipe-action" data-recipe-command="finish">Finish refresh</button></span>} />}{populated()}</div>;
  };
  const render = () => <section class="kui-recipe recipe-list kui-recipe__surface kui-layout" data-recipe="recipe-list-workspace-states" data-list-state={state.value}><PageHeader title="Release tasks" action={<div class="kui-control-cluster"><button class="kui-recipe__button" type="button" data-action="recipe-action" data-recipe-command="empty">Clear</button><button class="kui-recipe__button" type="button" data-action="recipe-action" data-recipe-command="fail">Simulate failure</button><button class="kui-recipe__button" data-primary="true" type="button" data-action="recipe-action" data-recipe-command="refresh">Refresh</button></div>} /><div class="recipe-list__body kui-scroll-owner kui-pane-body">{renderBody()}<p class="kui-recipe__ownership">The recipe owns feedback placement and stable content. The app owns fetching, cache age, retry policy, and domain rows.</p></div></section>;
  return { render, action(command) { const next: Record<string, ListState> = { load: 'populated', empty: 'empty', create: 'populated', fail: 'error', retry: 'populated', refresh: 'stale', finish: 'populated' }; if (command in next) state.value = next[command]!; announce(`List state: ${state.value}`); } };
};

--- ux-demo/recipes/compact-toolbar.tsx ---
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/select/register';
import './recipes.css';

import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import { Select } from '@kerfjs/ui/select';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { signal } from 'kerfjs';
import { Filter, MoreHorizontal, RefreshCw } from 'lucide';

import type { RecipeFactory } from './types.js';

export const createRecipe: RecipeFactory = (announce) => {
  const view = signal('list');
  const sort = signal('updated');
  const filtered = signal(false);
  const render = () => <section class="kui-recipe recipe-compact-toolbar kui-recipe__surface kui-layout" data-recipe="recipe-compact-toolbar">
    <Toolbar
      label="Task workspace controls"
      leading={<ToolbarText text="Tasks" size="small" />}
      center={<SegmentedControl id="recipe-view" label="View" value={view.value} action="recipe-action" appearance="toolbar" shape="pill" size="small" choices={[{ value: 'list', label: 'List' }, { value: 'board', label: 'Board' }, { value: 'timeline', label: 'Timeline' }]} />}
      trailing={<div class="kui-control-cluster"><Select name="recipe-sort" value={sort.value} ariaLabel="Sort tasks" fitMenu choices={[{ value: 'updated', label: 'Recently updated' }, { value: 'priority', label: 'Priority' }, { value: 'owner', label: 'Owner' }, { value: 'created', label: 'Created date' }]} /><ToolbarControlGroup label="Task actions" buttonAppearance="push"><button type="button" aria-label="Toggle filters" aria-pressed={String(filtered.value)} data-action="recipe-action" data-recipe-command="filter"><LucideIcon icon={Filter} name="filter" /></button><button type="button" aria-label="Refresh tasks" data-action="recipe-action" data-recipe-command="refresh"><LucideIcon icon={RefreshCw} name="refresh-cw" /></button></ToolbarControlGroup><button class="kui-recipe__button" type="button" aria-label="More task actions" data-action="recipe-action" data-recipe-command="more"><LucideIcon icon={MoreHorizontal} name="more-horizontal" /></button></div>}
    />
    <div class="recipe-compact-toolbar__guide kui-surface-body"><div><strong>ToolbarControlGroup</strong><span class="kui-recipe__muted">Related commands or pressed tools.</span></div><div><strong>SegmentedControl</strong><span class="kui-recipe__muted">A few visible exclusive choices.</span></div><div><strong>Select</strong><span class="kui-recipe__muted">A longer controlled value list.</span></div><div><strong>Ordinary button</strong><span class="kui-recipe__muted">One independent command.</span></div></div>
    <p class="kui-recipe__ownership kui-surface-body">The recipe owns control semantics and wrapping. The app owns values, actions, persistence, and responsive priority.</p>
  </section>;
  return {
    render,
    action(command, element) {
      const value = element.dataset.segmentValue;
      if (value) view.value = value;
      if (command === 'filter') filtered.value = !filtered.value;
      announce(value ? `View: ${value}` : command === 'filter' ? `Filters ${filtered.value ? 'on' : 'off'}` : `${command} requested`);
    },
    change(element) {
      const value = (element as HTMLElement & { value?: string }).value;
      if (element.getAttribute('name') === 'recipe-sort' && value) { sort.value = value; announce(`Sort: ${value}`); }
    },
  };
};

--- ux-demo/recipes/recipes.css ---
.kui-recipe { width: 100%; min-width: 0; color: var(--kui-color-text); container-type: inline-size; }
.kui-recipe button { font: inherit; }
.kui-recipe__button { min-height: 2rem; padding: var(--kui-space-xs) var(--kui-space-s); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); color: var(--kui-color-text); background: var(--kui-color-surface); cursor: pointer; }
.kui-recipe__button[data-primary="true"] { color: var(--kui-color-brand-on-normal); border-color: var(--kui-color-brand-border-normal); background: var(--kui-color-brand-fill-normal); }
.kui-recipe__button:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
.kui-recipe__surface { min-width: 0; overflow: hidden; border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-l); background: var(--kui-color-surface); box-shadow: var(--kui-shadow-s); }
.kui-recipe__pane-title { margin: 0; font-size: var(--kui-font-s); }
.kui-recipe__muted { color: var(--kui-color-text-quiet); font-size: var(--kui-font-s); }
.kui-recipe__ownership { margin: 0; color: var(--kui-color-text-quiet); font-size: var(--kui-font-xs); }

.recipe-shell { display: grid; height: min(37rem, 70vh); grid-template-rows: auto minmax(0, 1fr); }
.recipe-shell__body { display: flex; min-width: 0; min-height: 0; }
.recipe-shell__nav, .recipe-shell__inspector { display: grid; min-height: 0; grid-template-rows: auto minmax(0, 1fr); background: var(--kui-color-surface); }
.recipe-shell__nav-list, .recipe-shell__inspector-body, .recipe-shell__main-body { min-height: 0; }
.recipe-shell__main { display: grid; min-width: 16rem; min-height: 0; flex: 1; grid-template-rows: auto minmax(0, 1fr); background: var(--kui-color-surface-lowered); }
.recipe-shell__cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--kui-layout-section-gap); }
.recipe-shell__card { border: 1px solid var(--kui-color-border-quiet); border-radius: var(--kui-radius-m); background: var(--kui-color-surface); }

.recipe-sidebar { display: grid; width: min(22rem, 100%); min-height: 32rem; margin-inline: auto; grid-template-rows: minmax(0, 1fr) auto; }
.recipe-sidebar__body { min-height: 0; }
.recipe-sidebar__footer { border-block-start: 1px solid var(--kui-color-border); }
.recipe-sidebar__footer .kui-toolbar { min-height: auto; }

.recipe-header { display: grid; gap: var(--kui-layout-section-gap); }
.recipe-header__context { margin: 0; }
.recipe-header .kui-page-header__action { max-width: 100%; }

.recipe-master-detail { display: grid; width: min(58rem, 100%); min-height: 25rem; grid-template-columns: minmax(13rem, .8fr) minmax(18rem, 1.4fr); }
.recipe-master-detail__master { border-inline-end: 1px solid var(--kui-color-border); }
.recipe-master-detail__detail { min-width: 0; }
.recipe-dialog { --spacing: 0; --width: min(62rem, calc(100vw - 2rem)); }

.recipe-form { display: grid; width: min(38rem, 100%); margin-inline: auto; }
.recipe-form__fields { display: grid; gap: var(--kui-layout-section-gap); }
.recipe-form__error { margin: 0; color: var(--kui-color-danger-text); font-size: var(--kui-font-s); }

.recipe-list { display: grid; min-height: 27rem; grid-template-rows: auto minmax(0, 1fr); }
.recipe-list__body { min-height: 0; }
.recipe-list__items { display: grid; margin: 0; padding: 0; list-style: none; }
.recipe-list__items li { display: grid; padding-block: var(--kui-space-s); border-block-end: 1px solid var(--kui-color-border-quiet); gap: var(--kui-layout-metadata-gap); }
.recipe-list__items li:last-child { border-block-end: 0; }

.recipe-compact-toolbar { display: grid; gap: var(--kui-layout-section-gap); }
.recipe-compact-toolbar__guide { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--kui-layout-control-gap); }
.recipe-compact-toolbar__guide > div { padding: var(--kui-layout-pane-inset); border: 1px solid var(--kui-color-border-quiet); border-radius: var(--kui-radius-m); }
.recipe-compact-toolbar__guide strong, .recipe-compact-toolbar__guide span { display: block; }

@container (max-width: 44rem) {
  .recipe-shell__inspector-region { display: none; }
  .recipe-shell__cards, .recipe-compact-toolbar__guide { grid-template-columns: 1fr 1fr; }
  .recipe-master-detail { grid-template-columns: 1fr; }
  .recipe-master-detail__master { border-inline-end: 0; border-block-end: 1px solid var(--kui-color-border); }
  .recipe-compact-toolbar .kui-toolbar { height: auto; grid-template-columns: minmax(0, 1fr); grid-template-areas: "leading" "center" "trailing"; row-gap: var(--kui-layout-control-gap); }
  .recipe-compact-toolbar .kui-toolbar__leading { grid-area: leading; padding-inline-end: 0; }
  .recipe-compact-toolbar .kui-toolbar__center { grid-area: center; }
  .recipe-compact-toolbar .kui-toolbar__trailing { grid-area: trailing; justify-content: flex-start; }
  .recipe-compact-toolbar .kui-toolbar__trailing > .kui-control-cluster { width: 100%; }
  .recipe-compact-toolbar .kui-toolbar__trailing wa-select { min-width: min(12rem, 100%); flex: 1 1 12rem; }
}

@container (max-width: 28rem) {
  .recipe-shell__nav-region { display: none; }
  .recipe-shell__cards, .recipe-compact-toolbar__guide { grid-template-columns: 1fr; }
  .recipe-header .kui-page-header { align-items: flex-start; flex-direction: column; }
}

@media (prefers-reduced-motion: reduce) {
  .kui-recipe *, .kui-recipe *::before, .kui-recipe *::after { scroll-behavior: auto !important; animation-duration: 1ms !important; transition-duration: 1ms !important; }
}
